examples.template:
VStack(alignment: .leading, spacing: MonarchTokens.Space.space4) {
    MonarchFieldRenderer(
        MonarchFormFieldDefinition(id: {{fields.0.id}}, type: {{fields.0.type|case}}, label: {{fields.0.label}}, isRequired: {{fields.0.required}}),
        value: $answers[{{fields.0.id}}], confidence: {{prefilled.confidence}}
    )
    MonarchFieldRenderer(
        MonarchFormFieldDefinition(id: {{fields.1.id}}, type: {{fields.1.type|case}}, label: {{fields.1.label}}, description: {{fields.1.description}}, isRequired: {{fields.1.required}}),
        value: $answers[{{fields.1.id}}]
    )
    MonarchFieldRenderer(
        MonarchFormFieldDefinition(id: {{fields.2.id}}, type: {{fields.2.type|case}}, label: {{fields.2.label}}, options: [MonarchFormFieldOption(value: {{fields.2.options.0.value}}, label: {{fields.2.options.0.label}}), MonarchFormFieldOption(value: {{fields.2.options.1.value}}, label: {{fields.2.options.1.label}})]),
        value: $answers[{{fields.2.id}}]
    )
    MonarchFieldRenderer(
        MonarchFormFieldDefinition(id: {{fields.3.id}}, type: {{fields.3.type|case}}, label: {{fields.3.label}}),
        value: $answers[{{fields.3.id}}]
    )
    MonarchFieldRenderer(
        MonarchFormFieldDefinition(id: {{fields.4.id}}, type: {{fields.4.type|case}}, label: {{fields.4.label}}),
        value: $answers[{{fields.4.id}}]
    )
    MonarchFieldRenderer(
        MonarchFormFieldDefinition(id: {{fields.5.id}}, type: {{fields.5.type|case}}, label: {{fields.5.label}}, isRequired: {{fields.5.required}}, consentText: {{fields.5.consentText}}),
        value: $answers[{{fields.5.id}}]
    )
}

examples.code:
VStack(alignment: .leading, spacing: MonarchTokens.Space.space4) {
    MonarchFieldRenderer(
        MonarchFormFieldDefinition(id: "name", type: .shortText, label: "Full name", isRequired: true),
        value: $answers["name"], confidence: 0.92
    )
    MonarchFieldRenderer(
        MonarchFormFieldDefinition(id: "email", type: .email, label: "Email", description: "We only use it to reply.", isRequired: true),
        value: $answers["email"]
    )
    MonarchFieldRenderer(
        MonarchFormFieldDefinition(id: "where", type: .radio, label: "Where will you join from?", options: [MonarchFormFieldOption(value: "remote", label: "Remote"), MonarchFormFieldOption(value: "office", label: "Office")]),
        value: $answers["where"]
    )
    MonarchFieldRenderer(
        MonarchFormFieldDefinition(id: "relocate", type: .yesNo, label: "Can you relocate?"),
        value: $answers["relocate"]
    )
    MonarchFieldRenderer(
        MonarchFormFieldDefinition(id: "rating", type: .rating, label: "How was the process?"),
        value: $answers["rating"]
    )
    MonarchFieldRenderer(
        MonarchFormFieldDefinition(id: "consent", type: .consent, label: "Consent", isRequired: true, consentText: "I agree to be contacted about this request."),
        value: $answers["consent"]
    )
}
